import{_ as a,H as n,f as s,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"02｜规范驱动开发（SDD）：让 AI 永远在轨道上","description":"","frontmatter":{},"headers":[{"level":2,"title":"规范不是一次性的指令，是一套体系","slug":"规范不是一次性的指令-是一套体系","link":"#规范不是一次性的指令-是一套体系","children":[]},{"level":2,"title":"SDD 的完整工作流","slug":"sdd-的完整工作流","link":"#sdd-的完整工作流","children":[{"level":3,"title":"第一步：定规范","slug":"第一步-定规范","link":"#第一步-定规范","children":[]},{"level":3,"title":"第二步：AI按规范执行","slug":"第二步-ai按规范执行","link":"#第二步-ai按规范执行","children":[]},{"level":3,"title":"第三步：人验证输出","slug":"第三步-人验证输出","link":"#第三步-人验证输出","children":[]},{"level":3,"title":"第四步：迭代规范","slug":"第四步-迭代规范","link":"#第四步-迭代规范","children":[]}]},{"level":2,"title":"什么样的规范才有用","slug":"什么样的规范才有用","link":"#什么样的规范才有用","children":[{"level":3,"title":"具体，不模糊","slug":"具体-不模糊","link":"#具体-不模糊","children":[]},{"level":3,"title":"有优先级，不贪多","slug":"有优先级-不贪多","link":"#有优先级-不贪多","children":[]},{"level":3,"title":"带原因，不只是规则","slug":"带原因-不只是规则","link":"#带原因-不只是规则","children":[]}]},{"level":2,"title":"规范的分层","slug":"规范的分层","link":"#规范的分层","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级全链路开发实战/02｜规范驱动开发（SDD）：让AI永远在轨道上.md","filePath":"ClaudeCode企业级全链路开发实战/02｜规范驱动开发（SDD）：让AI永远在轨道上.md","lastUpdated":1779815375000}'),p={name:"ClaudeCode企业级全链路开发实战/02｜规范驱动开发（SDD）：让AI永远在轨道上.md"};function l(i,e,o,d,r,c){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="_02-规范驱动开发-sdd-让-ai-永远在轨道上" tabindex="-1">02｜规范驱动开发（SDD）：让 AI 永远在轨道上 <a class="header-anchor" href="#_02-规范驱动开发-sdd-让-ai-永远在轨道上" aria-label="Permalink to &quot;02｜规范驱动开发（SDD）：让 AI 永远在轨道上&quot;">​</a></h1><p>你好，我是Robert。</p><p>上一讲我们明确了一个核心认知：你是架构师，Claude Code是你的工程团队。你负责做决策，它负责执行。</p><p>但这里有一个问题：你怎么把你的决策传达给它？</p><p>你想想，如果你带过团队或者和外包合作过，你一定有体会，脑子里想得再清楚，如果没有落成文字，对方做出来的东西大概率和你想的不一样。口头说“帮我做个用户系统”，交回来你可能哪哪都不满意。但如果你给了接口文档、数据模型、命名规范、错误码定义，交付质量会好一个档次。</p><p>Claude Code也是一样。它很强，但它不会读心。你不告诉它规矩，它就自己编一套。每次编的还不一样。</p><p>这一讲要介绍的就是贯穿整门课的核心方法论： <strong>规范驱动开发（Specification-Driven Development，SDD）</strong>。一句话概括： <strong>先定规范，再让AI按规范执行，而不是直接让它写代码</strong>。</p><p>这是一节理论课，可能会有点枯燥，但是这节课是这门课的根基，AI既需要上下文，也需要规范。而规范的好坏决定了这个项目的质量。</p><p>我会从三个方面展开：先用一个真实场景让你直观感受规范体系的价值，然后讲SDD的完整工作流，最后聊规范的质量标准，什么样的规范才能真正约束住 AI。</p><h2 id="规范不是一次性的指令-是一套体系" tabindex="-1">规范不是一次性的指令，是一套体系 <a class="header-anchor" href="#规范不是一次性的指令-是一套体系" aria-label="Permalink to &quot;规范不是一次性的指令，是一套体系&quot;">​</a></h2><p><a href="https://time.geekbang.org/column/article/963290" target="_blank" rel="noreferrer">第 01 讲</a> 我们看到了一个现象：给Claude Code的指令越清晰，输出质量越高。但这里有一个容易被忽略的问题：你给的清晰指令，只在那一次对话里有效。</p><p>我拿Hify的真实经历来说明:</p><p>做Provider模块（模型提供商管理）时，我在指令里写得很细：实体叫Provider不加前缀、返回格式用Result&lt;T&gt;、错误码按模块分段、不要设计模式。Claude Code的输出很干净，命名统一、格式规范、结构简洁。</p><p>两天后做Agent模块，我写指令时没有重复那些规范（觉得它应该“记住”了），只说了“实现Agent的CRUD接口”。</p><p>伪代码如下：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Provider 模块</span></span>
<span class="line"><span>String instruction = &quot;实现 Provider 的 CRUD，实体不加后缀，返回 Result&amp;lt;T&amp;gt;，错误码从1000段，直接 new&quot;;</span></span>
<span class="line"><span>generate(instruction);</span></span>
<span class="line"><span>// → Provider.java / Result&amp;lt;T&amp;gt; / ERROR_1001 / new Provider()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Agent 模块</span></span>
<span class="line"><span>String instruction = &quot;实现 Agent 的 CRUD&quot;;</span></span>
<span class="line"><span>generate(instruction);  // 规范没带进来</span></span>
<span class="line"><span>// → AgentConfig.java / ResponseEntity / ERROR_1001（撞号）/ Agent.builder().build()</span></span></code></pre></div><p>拿到代码一看我皱眉了。</p><p>实体类叫AgentConfig——加了个Config后缀，Provider模块不加后缀，两个模块风格不一致。返回格式有的走Result&lt;T&gt;，有的直接返回ResponseEntity。错误码没有按模块分段，和Provider的错误码撞号了。更离谱的是它给Agent加了一个Builder模式——Provider模块用的是直接new，两个模块的创建方式都不一样。</p><p>每一条单独看都不是bug，功能完全正常。但放在一个项目里，两个模块两种风格，前端对接的时候要适配两套格式，后面维护的时候每个模块都要先搞清楚“这个模块的规矩是什么”。</p><p>问题出在哪？ <strong>Claude Code没有长期记忆。你上一轮对话给的规范，这一轮它完全不知道。它不是“忘了”，它根本没看到。每次新对话，对它来说都是从零开始</strong>。</p><p>所以单次指令的清晰度只能解决单次输出的质量。要保证整个项目几十次、几百次AI输出的一致性，你需要的不是一条好指令，是一套规范体系。写下来，每次自动加载，让Claude Code不管在哪个模块、哪个阶段，都在同一套规矩下工作。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/963294/3c39f8e95c8bc02aedb985aa99da3903.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/963294/3c39f8e95c8bc02aedb985aa99da3903.jpg" alt=""></a></p><p>这就是SDD和“写好 Prompt”的本质区别。 <strong>写好 Prompt 是一次性的技巧，SDD 是贯穿整个项目生命周期的方法论</strong>。</p><p>那具体怎么做？</p><h2 id="sdd-的完整工作流" tabindex="-1">SDD 的完整工作流 <a class="header-anchor" href="#sdd-的完整工作流" aria-label="Permalink to &quot;SDD 的完整工作流&quot;">​</a></h2><p>SDD不是写个规范然后照着做，它是一个持续运转的闭环。四步，循环往复。</p><h3 id="第一步-定规范" tabindex="-1">第一步：定规范 <a class="header-anchor" href="#第一步-定规范" aria-label="Permalink to &quot;第一步：定规范&quot;">​</a></h3><p>在写任何业务代码之前，先把基础规范定下来。</p><p>你可能会想：这得写到多细？会不会花太多时间？</p><p>第一版粗一点没关系，但一定要有。关键是覆盖Claude Code最容易跑偏的地方。根据我做Hify的经验，它最容易跑偏的地方有四个：</p><ul><li><strong>命名风格</strong>。不约束它，每个模块的命名都不一样。实体类加不加前缀、字段用驼峰还是下划线、接口路径用单数还是复数……这些它每次都要“猜”，猜的结果每次都不同。</li></ul><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 命名规范</span></span>
<span class="line"><span>实体类大驼峰，不加前缀后缀。例如 Provider、Agent、ChatMessage。</span></span>
<span class="line"><span>字段小驼峰。例如 apiKey、baseUrl、modelName。</span></span>
<span class="line"><span>接口路径：/api/v1/{资源复数名}。</span></span></code></pre></div><ul><li><strong>返回格式</strong>。不约束它，有的接口返回 <code>{&quot;code&quot;: 200, &quot;data&quot;: {...}​}</code>，有的返回 <code>{&quot;error&quot;: &quot;not found&quot;}</code>，有的直接返回ResponseEntity。前端适配的时候会崩溃。</li></ul><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 接口规范</span></span>
<span class="line"><span>所有接口统一返回 Result&amp;lt;T&amp;gt;：{ code, message, data }</span></span>
<span class="line"><span>列表字段空时返回空数组 []，不返回 null。</span></span>
<span class="line"><span>分页参数：page（从 1 开始）、pageSize（默认 20）。</span></span></code></pre></div><ul><li><strong>错误码体系</strong>。不约束它，错误码满天飞。有用HTTP状态码的，有用自定义字符串的，有用随机数字的。更糟的是不同模块的错误码撞号，你分不清2001到底是Provider的“网络超时”还是Agent的“模型不存在”。</li></ul><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 错误码</span></span>
<span class="line"><span>四位数字，按模块分段：</span></span>
<span class="line"><span>1000-1999 通用 | 2000-2999 Provider | 3000-3999 Agent</span></span>
<span class="line"><span>4000-4999 Chat | 5000-5999 MCP</span></span></code></pre></div><ul><li><strong>设计原则</strong>。这是最关键的一条。Claude Code训练数据里有大量“最佳实践”代码，它天然倾向于过度设计——工厂模式、策略模式、三层抽象、接口隔离。对一个几十人用的内部平台来说，大部分设计模式是负担不是资产。</li></ul><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 设计原则</span></span>
<span class="line"><span>不引入不必要的设计模式，除非明确要求。</span></span>
<span class="line"><span>不做过度抽象，一层能解决的不要拆成两层。</span></span>
<span class="line"><span>不引入技术栈以外的依赖，需要时先确认。</span></span></code></pre></div><p>四块加在一起，一页纸。但有和没有之间的差距，就是完成和完美之间的差距。</p><p>那这个规范从哪来？你可能已经有经验能写出大部分，但难免有遗漏。这里有个技巧：你也可以先让Claude Code帮你梳理“这个项目需要定哪些规范”，它帮你想，你来判断取舍。这种“先问再做”的协作模式，第09讲会专门展开。</p><p>规范写好了放哪里？ <strong>放在项目根目录的一个叫 CLAUDE.md 的文件里</strong>。Claude Code每次启动新对话时自动读取这个文件，你不需要每次手动喂。第05讲会手把手带你写完整版，这一讲你先理解它的作用。</p><h3 id="第二步-ai按规范执行" tabindex="-1">第二步：AI按规范执行 <a class="header-anchor" href="#第二步-ai按规范执行" aria-label="Permalink to &quot;第二步：AI按规范执行&quot;">​</a></h3><p>下达任务时，明确引用规范。不是“帮我做个Agent CRUD”，而是“按照CLAUDE.md中的规范，实现Agent的CRUD接口”。</p><p>这句话的重点不在“按照规范”这四个字，CLAUDE.md已经在上下文里了，Claude Code看得到。重点在于它提醒Claude Code去关注那份规范，而不是按自己的“经验”来。</p><p>有了CLAUDE.md之后，你回到做Agent模块那个场景：实体类就叫Agent不叫AgentConfig（因为规范写了“不加前缀后缀”），返回格式走Result&lt;T&gt;（因为规范写了“统一返回”），错误码从3000开始（因为规范写了“按模块分段”），没有Builder模式（因为规范写了“不引入不必要的设计模式”）。</p><p>同一个 AI，有规范体系和没有规范体系，输出的一致性完全不同。</p><h3 id="第三步-人验证输出" tabindex="-1">第三步：人验证输出 <a class="header-anchor" href="#第三步-人验证输出" aria-label="Permalink to &quot;第三步：人验证输出&quot;">​</a></h3><p>用第01讲的三步检查法， <strong>意图、质量、边界</strong>，检查Claude Code的输出是否符合规范。</p><p>有了规范之后，review的效率会大幅提升。因为你不再是漫无目的地看代码，而是“对着清单打勾”——命名是不是按规范来的？返回格式统一不统一？有没有引入我明确说了“不要用”的设计模式？错误码是不是在这个模块的分段范围内？</p><p>规范把review从主观判断变成了客观核查。这个转变对效率的提升是巨大的，你不需要每次都重新思考“这里应该怎么写”，因为标准已经定好了。</p><h3 id="第四步-迭代规范" tabindex="-1">第四步：迭代规范 <a class="header-anchor" href="#第四步-迭代规范" aria-label="Permalink to &quot;第四步：迭代规范&quot;">​</a></h3><p>这一步最关键，也最容易被忽略。</p><p>你在验证输出时，一定会发现规范没覆盖到的地方。这太正常了，你不可能第一次就想到所有情况。关键是每次发现缺口，都要补上。</p><p>我拿Hify开发过程中的真实案例来说明这个迭代过程。</p><p>第一周发现的缺口。Claude Code在处理空列表时返回了null。前端拿到null，页面直接白屏——它期望的是一个空数组 []。这说明规范里没定义“空值怎么处理”。补上：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>列表字段空时返回空数组 []，不返回 null。</span></span>
<span class="line"><span>字符串字段空时返回空字符串 &quot;&quot;，不返回 null。</span></span></code></pre></div><p>第二周发现的缺口。 做Agent模块时，让Claude Code改了一个Provider的接口签名。前端调Provider的代码全部报错。它“觉得”新签名更好，就顺手改了。这说明规范里缺少“改代码时的行为约束”。补上：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>修改已有代码前，先理解相关模块的设计意图。</span></span>
<span class="line"><span>不要为了实现新功能破坏已有模块的接口契约。</span></span></code></pre></div><p>第三周发现的缺口。做对话引擎时，Claude Code把业务逻辑写在了Controller里——事务管理、数据校验、外部调用全塞在一个方法。能跑，但完全不符合分层原则。这说明规范里缺少“代码放哪里”的约束。补上：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Controller 只做参数校验和调用 Service，不写业务逻辑。</span></span>
<span class="line"><span>跨模块调用走 Service 接口，不直接引用其他模块的 Mapper。</span></span></code></pre></div><p>做前端时发现的缺口。Claude Code引入了一个没在技术栈里的UI库。能跑，但多了一个依赖要维护。这说明规范里缺少“技术栈边界”的约束。补上：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不引入技术栈以外的依赖，需要时先问我。</span></span></code></pre></div><p>你看到规律了吗？ <strong>每次 AI 跑偏，不要只改代码——停下来问自己：它为什么跑偏？是不是规范没覆盖到？然后补上那条规范。</strong></p><p>这条规范一旦写进CLAUDE.md，后面所有对话都会受到约束。你不需要再遇到同样的问题。它跑偏一次，你补一条，以后它在这个点上就不会再跑偏。</p><p>坚持几周，你的规范会从最初的一页纸，长成一份覆盖命名规则、接口规范、错误码、异常处理、项目结构、分层原则、行为约束、前端组件规范的完整体系。Hify的规范就是这样长出来的，没有一条是“提前想出来的”，全部是在开发过程中一条一条补上去的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/963294/639275cbefa67b9360fe12075d4745e0.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/963294/639275cbefa67b9360fe12075d4745e0.jpg" alt=""></a></p><p>四步闭环用一句话概括：规范越磨越锋利，AI 越用越顺手。</p><h2 id="什么样的规范才有用" tabindex="-1">什么样的规范才有用 <a class="header-anchor" href="#什么样的规范才有用" aria-label="Permalink to &quot;什么样的规范才有用&quot;">​</a></h2><p>不是所有规范都能约束住AI。我在Hify的开发中踩过一些弯路，总结出三条判断标准。</p><h3 id="具体-不模糊" tabindex="-1">具体，不模糊 <a class="header-anchor" href="#具体-不模糊" aria-label="Permalink to &quot;具体，不模糊&quot;">​</a></h3><p>没用的规范：“代码要简洁。” Claude Code对“简洁”的理解和你不一样。它可能觉得一个工厂模式 + 策略接口就是简洁的抽象。</p><p>有用的规范：“不引入不必要的设计模式（工厂、策略、观察者等），除非明确要求。每个功能用最简单直接的方式实现。” 没有歧义，它知道工厂模式不能用。</p><p>没用的规范：“接口要规范。”</p><p>有用的规范：“所有接口统一返回 Result&lt;T&gt;，格式为 { code, message, data }。错误码四位数字，按模块分段。”</p><p>判断标准很简单：Claude Code看到这条规范后，是否还需要“猜”你的意思？如果还需要猜，就不够具体。</p><h3 id="有优先级-不贪多" tabindex="-1">有优先级，不贪多 <a class="header-anchor" href="#有优先级-不贪多" aria-label="Permalink to &quot;有优先级，不贪多&quot;">​</a></h3><p>规范不是越多越好。太多了Claude Code也处理不过来，因为上下文窗口是有限的，塞了太多规范反而会稀释重要的那几条。</p><p>我的原则是：AI反复跑偏的地方写细，不跑偏的地方不写。</p><ul><li><p>“文件编码用 UTF-8”，Claude Code基本不会搞错，不值得占篇幅。</p></li><li><p>“Controller不写业务逻辑”，它经常犯这个错，必须写。你的注意力应该放在它真正容易犯错的地方。</p></li></ul><p>Hify的CLAUDE.md最终大概两三页。不长，但每一条都是因为Claude Code在那个点上跑偏过才补上去的。没跑偏过的地方，一条都没有。</p><h3 id="带原因-不只是规则" tabindex="-1">带原因，不只是规则 <a class="header-anchor" href="#带原因-不只是规则" aria-label="Permalink to &quot;带原因，不只是规则&quot;">​</a></h3><p>这一条是我在做Agent模块时学到的。</p><p>第15讲做Agent工具列表更新时，我在指令里写了“不要全量删除再全量插入”。Claude Code第一版还是用了全量删除再插入——它不理解为什么不能这样做。</p><p>我补了一句解释：“全量删除再插入会导致并发场景下Agent瞬间失去所有工具关联，如果此时有对话正在读取工具列表，会拿到空列表。”</p><p>第二版它就用了差异比对的方式。</p><p>这说明一个问题：对于涉及工程权衡的规范，不能只告诉Claude Code “不要这样做”，还要告诉它为什么。它需要理解约束的原因，才能在类似场景中举一反三。此时它会跟你讨论，可能你想的不对。</p><p>不过，也不是每条规范都需要解释——“实体类不加前缀”不需要解释原因，照做就行。但“不破坏已有接口契约”、“不全量删除再插入”这类涉及工程判断的规范，加上原因会让Claude Code的遵循度明显更高。</p><h2 id="规范的分层" tabindex="-1">规范的分层 <a class="header-anchor" href="#规范的分层" aria-label="Permalink to &quot;规范的分层&quot;">​</a></h2><p>最后说一下规范的组织方式。随着项目推进，规范会越来越多，需要分层管理。</p><p>我把Hify的规范分成三层：</p><p><strong>全局规范</strong>。写在CLAUDE.md里，整个项目通用。命名规则、接口格式、错误码体系、设计原则、行为约束。项目初期定好，后面很少改动。这是地基。</p><p><strong>模块规范</strong>。某个模块开发前单独定义。比如Provider模块有自己的接口契约（第05讲会详细展示），对话模块有自己的数据流定义，工作流模块有自己的节点类型规范。写在模块目录下或者开发前的指令里。</p><p><strong>任务规范</strong>。每次给Claude Code下达具体任务时的补充说明。比如，“这次不需要分页”、“异常要区分这三种情况”、“用差异比对不要全量替换”。临时性的，不落成文档。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/963294/709d82a3fb7645f659481b0901da0a41.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/963294/709d82a3fb7645f659481b0901da0a41.jpg" alt=""></a></p><p>三层怎么配合？全局规范是地基，模块规范是补充，任务规范是临场微调。Claude Code每次干活时看到的，是三层叠加的完整约束。优先级从上到下——任务规范可以覆盖模块规范（这次不需要分页），但不能违反全局规范（所有接口统一返回Result&lt;T&gt;）。</p><p>第05讲会手把手带你写完整的CLAUDE.md，到时候你会看到全局规范的完整形态。这一讲我们先建立分层的认知。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这一讲的核心就是SDD的四步闭环： <strong>定规范→ AI 执行→人验证→迭代规范</strong>。</p><p>规范不是额外负担，是节省时间的捷径。没有规范的AI是一匹没有缰绳的马——跑得快，方向不可控。有了规范，你就把它框在轨道上了，又快又稳。</p><p>而且规范的价值会随时间复利累积。第一周你可能觉得“写规范好麻烦，直接让它干不就行了”。但到第三周，你会发现Claude Code几乎不跑偏了——不是它变聪明了，是你的规范把所有容易踩的坑都堵上了。后面每做一个新模块，规范帮你省下的review时间和返工时间，远超当初写规范的投入。</p><p>从实操角度，记住三件事：</p><p>第一，规范不需要一次写完。第一版覆盖最容易跑偏的四个地方（命名、返回格式、错误码、设计原则）就够了，后面在开发中迭代补全。</p><p>第二，每次AI跑偏了，不要只改代码，还要想想规范是不是该补一条。跑偏一次补一条，同样的问题不会再出现第二次。</p><p>第三，规范要具体到AI不需要猜你的意思。如果它看到规范后还需要“猜”，那就不够具体。</p><p>下一讲我们开始动手——定义Hify的产品边界，想清楚做什么和不做什么。这是“架构师”要做的第一件事，也是CLAUDE.md里最先要写的内容。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>试着做一个小练习：想一个你最近用AI写代码时反复遇到的问题，比如它总是命名不对，或者错误处理不统一，或者总是过度设计。然后为这个问题写一条具体的规范，要求满足这一讲说的三个标准：具体不模糊、有优先级、带原因（如果需要的话）。把你写的规范发在留言区，我们一起看看写得够不够精确。</p><p>期待你的分享。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,108)])])}const g=a(p,[["render",l]]);export{h as __pageData,g as default};
